var tree = get_tree()
var scene = tree.current_scene
Engine.max_fps = 120
var set_vector = func(v: Vector2):
    for axis in [JOY_AXIS_RIGHT_X, JOY_AXIS_RIGHT_Y]:
        var event = InputEventJoypadMotion.new()
        event.device = 0
        event.axis = axis
        event.axis_value = v.x if axis == JOY_AXIS_RIGHT_X else v.y
        Input.parse_input_event(event)
var wait_frames = func(count: int):
    for frame in range(count):
        await tree.process_frame
set_vector.call(Vector2.ZERO)
await wait_frames.call(3)
var angles = [-108.0,-144.0,180.0,144.0,108.0,72.0,36.0,0.0,-36.0,-72.0]
var names = ["L_UPPERCUT","L_HOOKERCUT","L_HOOK","L_FLARED","L_STRAIGHT","R_STRAIGHT","R_FLARED","R_HOOK","R_HOOKERCUT","R_UPPERCUT"]
var results = []
var passed = 0
for index in range(10):
    for offset in [-17.5,0.0,17.5]:
        var before = scene.log_rows.size()
        var angle = deg_to_rad(angles[index] + offset)
        set_vector.call(Vector2(cos(angle), -sin(angle)) * 0.95)
        await wait_frames.call(3)
        set_vector.call(Vector2.ZERO)
        await wait_frames.call(3)
        var rows = scene.log_rows.slice(before)
        var ok = rows.size() == 1 and rows[0].split(",")[1] == names[index]
        passed += int(ok)
        results.append({"angle_deg":angles[index]+offset,"expected":names[index],"rows":rows,"passed":ok})
return {"passed":passed,"total":30,"cases":results}
